def main():
    cols = ["id", "section", "te", "en", "emotion", "visual", "onscreen", "sound", "pacing", "cite"]
    with open(HERE / "script.full.tsv", "w", encoding="utf-8", newline="") as f:
        w = csv.writer(f, delimiter="\t", lineterminator="\n")
        w.writerow(cols)
        for i, (sec, en, vis, ons, snd, pace, cite) in enumerate(ROWS, 1):
            w.writerow([f"K{i:03d}", sec, "", en, "", vis, ons, snd, pace, cite])
    print(len(ROWS), "rows")


if __name__ == "__main__":
    main()
